// effectiveProxies returns the subset of configured proxies that are active,
// match the given protocol (case-insensitive), and are not excluded for the
// given hostname. A proxy with an empty Active field is treated as active.
// It returns nil when no proxies match.
func (s settings) effectiveProxies(protocol, hostname string) []Proxy {
	var proxies []Proxy
	for _, proxy := range s.Proxies {
		// A proxy is active unless its Active field is explicitly set to a
		// non-true value (e.g. "false"). An empty Active field is active.
		if proxy.Active != "" && !strings.EqualFold(proxy.Active, "true") {
			continue
		}
		if !strings.EqualFold(proxy.Protocol, protocol) {
			continue
		}
		if matchesNonProxyHosts(hostname, proxy.NonProxyHosts) {
			continue
		}
		proxies = append(proxies, proxy)
	}
	return proxies
}

// matchesNonProxyHosts reports whether hostname matches any of the pipe-separated
// glob patterns in nonProxyHosts (e.g. "localhost|*.example.com").
func matchesNonProxyHosts(hostname, nonProxyHosts string) bool {
	if nonProxyHosts == "" {
		return false
	}
	for _, pattern := range strings.Split(nonProxyHosts, "|") {
		pattern = strings.TrimSpace(pattern)
		if pattern == "" {
			continue
		}
		if matched, err := filepath.Match(pattern, hostname); err == nil && matched {
			return true
		}
	}
	return false
